{
 "command": "cd services/notifier && find . -type f -not -path '*/node_modules/*' | head -50 && cat *.py 2>/dev/null | head -150; ls tests; cat tests/*.py | head -150",
 "description": "Explore notifier service files"
}

{
 "command": "cat README.md pyproject.toml notifier/*.py; cat ../../Makefile 2>/dev/null; grep -rn \"integration\\|markers\\|sink\" ../../pyproject.toml ../../setup.cfg ../../pytest.ini ../../conftest.py 2>/dev/null",
 "description": "Read notifier source and config"
}

{
 "command": "cd ../.. && sed -n 1,30p pyproject.toml; grep -rni \"sink\\|inbox\\|mailprovider\" --exclude-dir=.git . | grep -v \"^./services/notifier/notifier/provider.py\"",
 "description": "Check pytest markers and sink inbox references"
}

{
 "command": "cd services/notifier && python -m pytest --import-mode=importlib tests -q -rs 2>&1 | tail -8",
 "description": "Run notifier tests"
}
